Object.assign(window.DYLEAN_DATA.files["Library/Init/Data/Nat/Order.lean"],{"text":"/-\nCopyright (c) 2025 Lean FRO, LLC. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Paul Reichert\n-/\nmodule\n\nprelude\npublic import Init.Data.Nat.Basic\nimport Init.Data.Nat.MinMax\npublic import Init.Data.Order.Classes\nimport Init.Data.Order.Factories\nimport Init.NotationExtra\n\nopen Std\n\nnamespace Nat\n\npublic instance instIsLinearOrder : IsLinearOrder Nat := by\n  apply IsLinearOrder.of_le\n  · constructor; apply Nat.le_antisymm\n  · constructor; apply Nat.le_trans\n  · constructor; apply Nat.le_total\n\npublic instance : LawfulOrderLT Nat := by\n  apply LawfulOrderLT.of_le\n  simp [Nat.lt_iff_le_and_ne]\n\npublic instance : LawfulOrderMin Nat := by\n  apply LawfulOrderMin.of_le_min_iff\n  · apply Nat.le_min\n  · intro a b\n    simp only [Nat.min_def]\n    split <;> simp\n\npublic instance : LawfulOrderMax Nat := by\n  apply LawfulOrderMax.of_max_le_iff\n  · apply Nat.max_le\n  · intro a b\n    simp only [Nat.max_def]\n    split <;> simp\n\nend Nat\n","refs":[[18,16,18,33,"d4e2d6f1a98d",true],[18,36,18,49,"7f22b0abd9a3",false],[18,50,18,53,"1a9353d78c15",false],[19,8,19,27,"c2c0a7ecc13d",false],[20,23,20,38,"1e57c1c713cc",false],[21,23,21,35,"b93066fb6f8f",false],[22,23,22,35,"a79b926e59b6",false],[24,18,24,31,"113f9836a4a5",false],[24,32,24,35,"1a9353d78c15",false],[28,18,28,32,"3f6e3dd822d6",false],[28,33,28,36,"1a9353d78c15",false],[32,15,32,26,"13ecfd326960",false],[35,18,35,32,"cccdcf0f1c99",false],[35,33,35,36,"1a9353d78c15",false],[39,15,39,26,"020eed7a3fb3",false]]});
